export async function openImageExportDialog(page) {
    await page.getByTestId("main-menu-trigger").click();
    await page.getByTestId("image-export-button").click();
}

export async function copyImageToClipboard(page) {
    await page.getByRole("button", { name: "Copy PNG to clipboard" }).click();
}

export async function exportImageAs(page, format) {
    await page.getByRole("button", { name: format }).click();
}

export async function drawRectangleOnCanvas(page, startX, startY, endX, endY) {
    await page.getByTestId("toolbar-rectangle").waitFor({ state: "attached", timeout: 10000 });
    await page.keyboard.press("r");
    await page.mouse.move(startX, startY);
    await page.mouse.down();
    await page.mouse.move(endX, endY, { steps: 12 });
    await page.mouse.up();
}
